        }

        // Initialize dp array
        memset(dp, -1, sizeof(dp));
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            int w = weights[i];
            for (int j = 0; j <= 10; j++) {
                // Not using current dumpling
                dp[i][j] = dp[i-1][j];

                // Using current dumpling
                if (j >= w && dp[i-1][j-w] != -1) {
                    int new_val = dp[i-1][j-w];
                    if (j == 10) {
                        new_val++; // complete a bundle
                        if (dp[i][j] < new_val) {
