                        if (dp[i][j] < new_val) {
                            dp[i][j] = new_val;
                        }
                    }
                }
            }
        }

        // Find maximum bundles
        int max_bundles = 0;
        for (int i = 0; i <= n; i++) {
            if (dp[i][10] > max_bundles) {
                max_bundles = dp[i][10];
            }
        }

        printf("%d\n", max_bundles);
    }
    return 0;
