int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        int cnt[11];
        memset(cnt, 0, sizeof(cnt));

        for (int i = 0; i < n; i++) {
            int x;
            scanf("%d", &x);
            if (1 <= x && x <= 10) cnt[x]++;
        }

        int ans = 0;

        /* 5 + 5 */
        ans += cnt[5] / 2;
        cnt[5] %= 2;

        /* pairs summing to 10: (1,9), (2,8), (3,7), (4,6) */
        for (int i = 1; i <= 4; i++) {
            int m = cnt[i] < cnt[10 - i] ? cnt[i] : cnt[10 - i];
            ans += m;
            cnt[i] -= m;
            cnt[10 - i] -= m;
        }

        /* triples */
        for (int a = 1; a <= 10; a++) {
            for (int b = a; b <= 10; b++) {
                int c = 10 - a - b;
                if (c < b || c > 10) continue;

                if (a == b && b == c) {
                    int m = cnt[a] / 3;
                    ans += m;
                    cnt[a] -= 3 * m;
                } else if (a == b) {
                    int m = cnt[a] / 2;
                    if (cnt[c] < m) m = cnt[c];
                    ans += m;
                    cnt[a] -= 2 * m;
                    cnt[c] -= m;
                } else if (b == c) {
                    int m = cnt[b] / 2;
                    if (cnt[a] < m) m = cnt[a];
                    ans += m;
                    cnt[a] -= m;
                    cnt[b] -= 2 * m;
                } else {
                    int m = cnt[a];
                    if (cnt[b] < m) m = cnt[b];
                    if (cnt[c] < m) m = cnt[c];
                    ans += m;
                    cnt[a] -= m;
                    cnt[b] -= m;
                    cnt[c] -= m;
                }
            }
        }

        /* quadruples and more are unnecessary because all weights are positive
           integers <= 10, and after taking all possible 2- and 3-item groups,
           no larger group can increase the count. */

        printf("%d\n", ans);
    }
    return 0;
}

