using namespace std;

int main() {
    int n;
    while (cin >> n && n != 0) {
        vector<int> w(n);
        for (int i = 0; i < n; i++) cin >> w[i];

        int total = 1 << n;
        vector<int> sumOf(total, 0);

        // Compute sum for each subset
        for (int mask = 1; mask < total; mask++) {
            int lsb = mask & (-mask);
            int bit = __builtin_ctz(lsb);
            sumOf[mask] = sumOf[mask ^ lsb] + w[bit];
        }

        // dp[mask] = max bundles using subset of dumplings given by mask
        vector<int> dp(total, 0);

        for (int mask = 1; mask < total; mask++) {
            // Find lowest set bit in mask
            int lsb = mask & (-mask);
            int bit = __builtin_ctz(lsb);

            // dp[mask] without using bit at all (but we must consider it)
            // Actually dp[mask] = best we can do with exactly these dumplings available
            // We can choose not to use some dumplings

            // First, dp[mask] >= dp[mask ^ lsb] (don't use the lowest bit dumpling)
            dp[mask] = dp[mask ^ lsb];

            // Try all submasks of mask that include lsb and sum to 10
            // Enumerate submasks of mask that include lsb
            int rest = mask ^ lsb; // mask without lsb
            // submask of mask containing lsb = lsb | (submask of rest)
            for (int sub = rest; ; sub = (sub - 1) & rest) {
                int s = sub | lsb;
                if (sumOf[s] == 10) {
                    dp[mask] = max(dp[mask], dp[mask ^ s] + 1);
                }
                if (sub == 0) break;
            }
        }

        cout << dp[total - 1] << endl;
    }
    return 0;
}

