import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            int[] w = new int[n];
            for (int i = 0; i < n; i++) {
                w[i] = sc.nextInt();
            }

            // Find all subsets that sum to 10
            List<Integer> validMasks = new ArrayList<>();
            for (int mask = 1; mask < (1 << n); mask++) {
                int sum = 0;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        sum += w[i];
                    }
                }
                if (sum == 10) {
                    validMasks.add(mask);
                }
            }

            // DP: dp[mask] = max number of groups using exactly the dumplings in mask
            int[] dp = new int[1 << n];
            Arrays.fill(dp, -1);
            dp[0] = 0;

            for (int mask = 0; mask < (1 << n); mask++) {
                if (dp[mask] < 0) continue;
                // Try to add one more group
                for (int vm : validMasks) {
                    if ((mask & vm) == 0) { // no overlap
                        int newMask = mask | vm;
                        if (dp[newMask] < dp[mask] + 1) {
                            dp[newMask] = dp[mask] + 1;
                        }
                    }
                }
            }

            int ans = 0;
            for (int mask = 0; mask < (1 << n); mask++) {
                if (dp[mask] > ans) ans = dp[mask];
            }

            System.out.println(ans);
        }
    }
}

